import { 
  ActivityIndicator,
  Image,  
  Text as RNText, 
  TextInput as RNTextInput, 
  Pressable, 
  View, 
  Switch as RNSwitch,
} from 'react-native';

import { RFPercentage, RFValue } from "react-native-responsive-fontsize";
import SelectDropdown from 'react-native-select-dropdown';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import {
  Icon as NIcon,
} from './Icons';

import { isWeb, isIos } from '../utils';

export const fontFamily = isIos ? 'Roboto Flex' : 'Roboto-Flex';

const refSize = 640;
export const resizeRel = (size) => {
  return isWeb ? size : RFValue(size, refSize);
}

export const fontSizes = {
  xs: resizeRel(9),
  s: resizeRel(12),
  m: resizeRel(14),
  l: resizeRel(16),
  xl: resizeRel(18),
  xxl: resizeRel(20),
}

export const COLORS = {
  primary: '#2D69AF',
  warning: '#fec514',
  danger: '#C41818',
  success: '#4DC418',
  secondary: '#4DC418',

  borderColor: '#E2E6F0',
  backColor: '#F5F5F5',
  app: '#ffffff',

  textPrimary: '#313131',
  textSecondary: '#9C9C9C'
}

export const BORDERCOLOR = COLORS.borderColor;
export const BACKCOLOR = COLORS.backColor;

export const Text = ({ children, style, ...props }) => 
  <RNText style={[{ fontFamily, color: COLORS.textPrimary, fontSize: fontSizes.m }, style ]} {...props}>
    {children}
  </RNText>

export const Title = ({ children, style }) =>
  <Text
    style={[{ fontSize: fontSizes.l, fontWeight: 'bold', paddingBottom: 10 }, style]}
  >
    {children}
  </Text>

export const TextInput = ({ style, ...props }) => {
  const webStyle = isWeb ? { outlineStyle: 'none' } : {}
  const defStyle = { fontFamily, color: COLORS.textPrimary }
  const disabledStyle =  props.disabled ? { backgroundColor: BACKCOLOR } : {}

  return (
    <RNTextInput 
      style={[defStyle, webStyle, disabledStyle, style ]} 
        {...props} 
    />
  )
}

export const Select = ({ 
    value, 
    options, 
    onChange, 
    buttonStyle,
    buttonTextStyle,
    rowTextStyle,
    iconStyle,
    renderCustomizedButtonChild,
    renderCustomizedRowChild,
  }) => {
    const fontStyle = { flex: 1, textAlign: 'left', fontFamily, fontSize: fontSizes.m }
    const childHeight = resizeRel(50); 
    const maxItems = 3;

    if (!renderCustomizedRowChild)
      renderCustomizedRowChild = ({label, text}) =>
        <Text style={[fontStyle, rowTextStyle]}>{label || text}</Text>

    return (
    <SelectDropdown
      data={options}
      defaultValueByIndex={options.findIndex((item) => item.value === value ) || 0}
      onSelect={(item) => onChange?.(item.value)}
      buttonTextAfterSelection={({ label, text }) => label || text}
      rowTextForSelection={({ label, text }) => label || text}
      
      buttonStyle={[{
        height: childHeight,
        width: '100%',
        backgroundColor: COLORS.app,
        borderColor: BORDERCOLOR,
        borderRadius: 8,
        borderWidth: 1,
      }, buttonStyle]}

      buttonTextStyle={[fontStyle, buttonTextStyle]}
      renderDropdownIcon={() => <Icon icon="chevron-down" { ...iconStyle }/>}
      renderCustomizedButtonChild={renderCustomizedButtonChild}
      renderCustomizedRowChild={(item, idx) => (
        <View style={[{ padding: 10, minHeight: childHeight }]} >
          {renderCustomizedRowChild(item, idx)}
        </View>
      )}
      dropdownStyle={{ top: 200, position: 'absolute', minHeight: childHeight * Math.min(options.length, maxItems) }}
    />
  )
}

export const Switch = (props) => 
  <RNSwitch activeTrackColor={COLORS.borderColor} activeThumbColor={COLORS.primary} {...props} />;

export const Button = ({ children, color, style, onClick, testID, fullWidth }) => {
  const backgroundColor = COLORS[color] || color;

  let stylex = { backgroundColor, minWidth: 100, height: 40, borderRadius: 5,  flexDirection: 'row', alignItems: 'center', justifyContent: 'center', color: 'white' }
  if ( fullWidth ) stylex = { ...stylex, flex:1 }
  
  return (
    <Pressable 
      testID={testID}
      style={[stylex, style]}
      onPress={onClick} 
    >
      {children}
    </Pressable>
  )
}

export const Icon = ({ icon, size, color = COLORS.textPrimary }) => {
  size = isWeb ? size : RFPercentage(3);
  const styling = { icon, size, color: COLORS[color] || color }
  return <NIcon {...styling} />
}

export const CallIcon = ({
  call = {},
  ...props
}) => {
  const { direction } = call;
  const color = props.color ? props.color : call.status === 'answered' ? COLORS.textSecondary : COLORS.danger
  if (direction === 'inbound')
    return <Icon icon="phone-incoming" {...props} color={color} />;

  return <Icon icon="phone-outgoing"  {...props} color={color} />;
}

export const ButtonIcon = ({ children, icon, onClick, style, color, testID, size = 18 }) => {
  const Container = onClick ? Pressable : View;
  return (
    <Container
      testID={testID}
      onPress={onClick}
      style={[
        { flexDirection: 'row', alignItems: 'center', justifyContent: 'center' },
        style
      ]}
    >
      { icon && <Icon {...{icon, size, color }} />}
      {children}
    </Container>
  )
}

export const RoundIconButton = ({ size = 30, color, iconSize, iconColor, style, ...props }) => {
  size = resizeRel(size);
  iconSize = resizeRel(iconSize);
  return (
    <ButtonIcon 
      {...props}
      color={iconColor} 
      size={iconSize} 
      style={[{ 
        width: size,
        height: size,
        borderRadius: size / 2,
        justifyContent: 'center',
        alignItems: 'center',
        backgroundColor: color}, style]}
    />
  )
}

export const CallButton = ({ style, size = 30, iconSize = 20, ...props }) => {
  return (
  <RoundIconButton 
    {...props}
    size={size} 
    iconSize={iconSize}
    style={style} 
  />)
}

export const Link = ({ children, style = {}, onClick }) => (
  <Pressable onPress={() => onClick?.()}>
    <Text style={{ ...style }}>{children}</Text>
  </Pressable>
)

export const Loader = () => (
  <View
    style={{
      flex: 1,
      justifyContent: 'center',
      alignItems: 'center'
    }}
  >
    <ActivityIndicator size="large" />
  </View>
)

export const HRule = ({ color = BORDERCOLOR }) => (
  <View
    style={{
      marginVertical: 10,
      borderBottomWidth: 1,

      borderBottomColor: color
    }}
  />
)

export const CancelAccept = ({ onCancel, onAccept, acceptTestID, cancelTestID }) => (
  <View
    style={{
      flexDirection: 'row',
      justifyContent: 'space-around',
      alignItems: 'center',
    }}
  >
    {onCancel && (
      <Button testID={cancelTestID} color="danger" onClick={onCancel} fullWidth={!onAccept}>
        <Icon icon="x" color='white' />
      </Button>
    )}

    {onAccept && (
      <Button testID={acceptTestID} color="secondary" onClick={onAccept} fullWidth={!onCancel}>
        <Icon icon="check" color='white' />
      </Button>
    )}
  </View>
)

export const CancelAcceptCall = ({ onCancel, onAccept, cancelTestID, acceptTestID, iconSize = 50 }) => (
  <View
    style={{
      flexDirection: 'row',
      justifyContent: 'space-around',
      alignItems: 'center',
    }}
  >
    {onCancel && (
      <RoundIconButton
        testID={cancelTestID}
        size={iconSize}
        color={COLORS.danger}
        iconColor="white" 
        icon="phone"
        onClick={onCancel}
      />
    )}

    {onAccept && (
      <RoundIconButton
        testID={acceptTestID}
        size={iconSize}
        color={COLORS.secondary}
        iconColor="white" 
        icon="phone"
        onClick={onAccept}
      />
    )}
  </View>
)

export const Avatar = ({ 
  source, 
  name = '', 
  size = 35 }) => {
  size = resizeRel(size);
  const letters = name.split(/\s+/g).map(chunk => chunk[0]).join('').substring(0, 3).toUpperCase()
  
  const stringToHslColor = (str, s, l) => {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = str.charCodeAt(i) + ((hash << 5) - hash)
    }
  
    const h = hash % 360;
    return 'hsl('+h+', '+s+'%, '+l+'%)';
  }

  return (
    <View style={{
      justifyContent: 'center',
      alignItems: 'center',
      backgroundColor: stringToHslColor(name, 30, 80),
      width: size, height: size, borderRadius: size / 2
    }}>

      <Text   
        numberOfLines={1} 
        ellipsizeMode='tail' 
        style={{ fontSize: size * 0.4 }}>
          {letters}
      </Text>

      {source &&
      <Image source={source} 
        style={[{ width: size, height: size, borderRadius: size / 2 }, {position: 'absolute'}]} />
      }
    </View>
    )
}

const ImageAvatar = require('../../assets/avatar.png')
export const AvatarContact = ({ contact = {}, ...props }) => {
  const { name, avatar } = contact;

  return (
    <Avatar
      {...props}
      name={name}
      source={avatar?.length > 0 ? { uri: avatar } : name ? undefined : ImageAvatar}
    />
  )
}

export const AvatarUser = ({
  color,
  avatar,
  ...props
}) => {
  return (
    <View>
      <Avatar size={50} {...props} source={avatar ? { uri: avatar } : ImageAvatar} />
      <Status color={color} size={12} style={{ position: 'absolute', bottom: 0, right: 0 }} />
    </View>
  )
}

export const Status = ({ color, size = 10, style }) => {
  size = resizeRel(size);
  const roundstyle = {
    width: size,
    height: size,
    borderRadius: size / 2,
    backgroundColor: color || 'black'
  }

  return <View style={{ ...style, ...roundstyle }} />;
}

export const Screen = ({
  children,
  bodyStyle,
  onClose,
  closeable,
  style,
  visible,
  color = COLORS.app,
  ...rest
}) => {
  if (!visible) return null;

  const insets = isWeb ? {} : useSafeAreaInsets()
  const defStyle = { height: '100%', width: '100%', position: 'absolute', backgroundColor: color, ...insets }

  return (
    <View style={[defStyle]} {...rest}>
      <View style={[{ flex: 1 }, bodyStyle]}>
        {closeable && (
          <ButtonIcon 
            style={[{ position: 'absolute', top: 10, right: 10, zIndex: 1000 }]} 
            size={21} onClick={() => onClose?.()} icon='x' />
        )}

        {children}
      </View>
    </View>
  )
}

export const TextField = ({
  onChange,
  onKeyPress,
  placeholder,
  style,
  password,
  ...props
}) => {

  const defaultStyle = {
    fontFamily, 
    fontSize: fontSizes.m,
    borderColor: BORDERCOLOR,
    borderWidth: 1,
    padding: 10,
    borderRadius: 5
  }

  return (
    <TextInput
      style={[{ ...defaultStyle }, style]}
      onChangeText={onChange}
      secureTextEntry={password}
      placeholder={placeholder}
      placeholderTextColor={COLORS.textSecondary}
      autoCapitalize="none"
      {...props}
    />
  )
}

export const FormRow = ({ children, label, style = {} }) => (
  <View style={{ width: '100%', paddingVertical: 10, ...style }}>
    {label && (
      <Text style={{ paddingBottom: 5, fontSize: fontSizes.s, fontWeight: 500 }}>
        {label}
      </Text>
    )}
    {children}
  </View>
)

export const InputRow = ({ label, ...rest }) => (
  <FormRow label={label}>
    <TextField testID={label} {...rest} />
  </FormRow>
)
