import _ from 'lodash';

import { 
  COLORS, 
  Status, 
  ButtonIcon, 
  FormRow, 
  InputRow, 
  HRule, 
  Select, 
  CancelAccept, 
  Button, 
  Text, 
  Switch, 
  Icon, 
  Screen, 
  Title,

  fontFamily,
  fontSizes
} from './Basics';

import { WebhooksList, EventsList } from './Lists';

import { useStore } from '../phone/store';
import { isWeb } from '../utils';

const SelectDevice = ({ devices, deviceId, onChange }) => (
  <Select
    tabIndex="-1"
    options={devices.map(({ deviceId, label }) => {
      return { value: deviceId, text: label };
    })}
    value={deviceId}
    onChange={onChange}
  />
)

const StatusText = ({ text, color } = {}) => (
  <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center' }}>
    <View style={{ paddingRight: 10 }} >
      <Status color={color} />
    </View>
    <Text>{text}</Text>
  </View>
)

export const StatusForm = ( { style, onChange, ...initialValues }) => {
  const [values, setValues] = useState(initialValues);

  const setValue = (field, value) => {
    const val = { ...values };
    val[field] = value;

    setValues(val);
    onChange?.(val);
  };

  useEffect(() => {
    if (!_.isEqual(initialValues, values)) setValues(initialValues);
  }, [initialValues]);

  const { statuses = [], status } = values;

  if (!statuses.length) return null;

  return (
    <View style={style}>
      <FormRow label={'Status'}>
        <Select
          options={statuses}
          value={status}
          renderCustomizedButtonChild={(item) => {
            const status = statuses.find(status => status.value === item?.value)
            return <StatusText { ...status }/>
          }}
          renderCustomizedRowChild={(_, idx) => <StatusText { ...statuses[idx] } />}
          onChange={val => setValue('status', val)}
        />
      </FormRow>
    </View>
  );
};

