export const DangerZone = ({ style }) => {
  const { clear } = useStore();

  const handleClear = () => {
    const message = 'Are you sure you want to clear all data?'

    if (isWeb) {
      if (confirm(message)) 
        clear();
      
    } else {
      Alert.alert('Clear All', message, [
        {
          text: 'Cancel',
          style: 'cancel',
        },
        {
          text: 'OK', 
          onPress: clear
        },
      ]);
    }
  }

  return (
    <View style={ style }>
      <Title style={{ fontSize: fontSizes.m, color: 'red' }}>Danger Zone</Title>
      <Button 
        color='danger' 
        onClick={handleClear}
      >
        <Text style={{ color: 'white' }}>Clear all</Text>
      </Button>
    </View>
  )
}

export const QView = () => {
  const store = useStore();

  const {
    qTts,
    qSummarization,
    webhooks,
    events,

    setState,
  } = store;

  // return null;

  const renderScene = ({ route }) => {
    switch (route.key) {
      case 'webhooks':
        return <WebhooksList data={webhooks} />;
      case 'logs':
        return <EventsList data={events} />;
      default:
        return null;
    }
  };

  const layout = useWindowDimensions();

  const [index, setIndex] = useState(0);
  const [routes] = useState([
    { key: 'logs', title: 'Events' },
    { key: 'webhooks', title: 'Webhooks' },
  ]);

  const renderTabBar = props => (
    <TabBar
        getLabelText={({ route }) => route.title}
        indicatorStyle={{ backgroundColor: COLORS.primary }}
        style={{ backgroundColor: COLORS.app, elevation: 0 }}
        labelStyle={{ color: COLORS.textPrimary, fontSize: fontSizes.s, fontFamily }}
        {...props}
    />
  );

  return (
    <View style={{ flex: 1 }}>
      <Title>Events</Title>

      {isWeb &&
        <View>
          <View style={{ flexDirection: 'row',  justifyContent: 'space-between', padding: 5 }}>
            <Text>Transcribe</Text>
            <Switch value={qTts} onValueChange={() => {
              const value = !qTts;
              value ? setState({ qTts: value }) : setState({ qTts: false, qSummarization: false })
            }} />
          </View>

          <View style={{ flexDirection: 'row',  justifyContent: 'space-between', padding: 5 }}>
            <Text>Summarize</Text>
            <Switch value={qSummarization} onValueChange={() => setState({ qSummarization: !qSummarization })} />
          </View>

          <HRule />
        </View>
      }

      <TabView
        navigationState={{ index, routes }}
        onIndexChange={setIndex}
        renderScene={renderScene}
        renderTabBar={renderTabBar}
        initialLayout={{ width: layout.width }}
        sceneContainerStyle={{ paddingTop: 10 }}
      />
    </View>
  )
}

const UserForm = () => {
  const store = useStore();

  const {
    settingsUri,
    authToken,
    login,
    loginManaged,

    nickname,
    password
  } = store;
  
  const [connection, setConnection] = useState({
    settingsUri,
    authToken
  });

  const [managed, setManaged] = useState({
    nickname,
    password
  });

  useEffect(() => {
    setConnection({ settingsUri, authToken });
  }, [settingsUri, authToken]);

  useEffect(() => {
    setManaged({ nickname, password });
  }, [nickname, password]);

  const onChangeConnectionHandler = input => {
    setConnection(input);
  };

  const onChangeManagedHandler = input => {
    setManaged(input);
  };

  return (
    <View style={{ flex: 1 }}>
     
      <ScrollView style={{ flexGrow: 1 }}>
         <Title>User</Title>
         {isWeb && false &&
          <ConnectionForm 
            {...connection}
            onChange={onChangeConnectionHandler}
          />
         }

        {/*!isWeb*/ true &&
          <UserPassForm {...managed} onChange={onChangeManagedHandler} />
        }

        <View style={{ marginTop: 10 }}>
          <CancelAccept
            onCancel={() => setConnection({ settingsUri, authToken })}
            onAccept={async () => {
              try {
                if (isWeb)
                  await loginManaged(managed); // await login(connection);
                else
                  await loginManaged(managed);

                const message = 'Login Successful';
                if (isWeb) {
                  alert(message);
                } else {
                  Alert.alert('Success', message);
                }
              } catch(err) {
                const message = 'Login Failed';
                if (isWeb) {
                  alert(message);
                } else {
                  Alert.alert('Failed', message);
                }

                console.error(err);
              }
            }}
            acceptTestID="settingsAccept"
          />
        </View>
      </ScrollView>

      <HRule />
      <DangerZone style={{ paddingVertical: 10 }} />
    </View>
  )
}

export const SettingsScreen = ({ visible = false, closeable = true, onClose }) => {
  const store = useStore();
  
  const {
    anchored,
    electron,
    qVisible,

    setState,
  } = store;

  const [option, setOption] = useState('settings');

  const onChangeSettingsHandler = input => {
    setState(input);
  };

  const content = {
    settings: (
      <View style={{ flex: 1 }}>
        <ScrollView style={{ flexGrow: 1 }}>
          <View style={{ flex: 1 }}>
            <StatusForm {...store} onChange={onChangeSettingsHandler} />
            {isWeb &&
              <View>
                <HRule />
                <DevicesForm {...store} onChange={onChangeSettingsHandler} />
              </View>
            }
          </View>

        </ScrollView>
      </View>
    ),
    user: <UserForm />,
    events: <QView />
  };

  let opts = [
    { option: 'settings', icon: 'settings' },
    { option: 'user', icon: 'user' },
  ]

  if (qVisible)
    opts.push({ option: 'events', icon: 'share-2' });

  return (
    <Screen
      visible={visible}
      closeable={closeable}
      onClose={onClose}
    >
      <View  style={{ flex: 1, flexDirection: 'row' }}>
        
        <View style={{ justifyContent: 'space-between' }} >
          <View key={option} style={{ flex: 1, backgroundColor: COLORS.backColor }}>
            {opts.map((opt, i) => {
              const selected = option === opt.option 
              return (
                <ButtonIcon
                  key={`opt-${i}a`}
                  style={{ padding: 20, backgroundColor: selected ? COLORS.app : null }}
                  icon={opt.icon}
                  color={selected ? COLORS.primary : undefined}
                  onClick={() => setOption(opt.option)} 
                />
              )})}
          </View>

          {electron &&
            <View style={{ backgroundColor: COLORS.backColor }}>
              <ButtonIcon
                style={{ padding: 20 }}
                icon={anchored ? 'unanchor' : 'anchor'}
                onClick={() => setState({ anchored: !anchored })} 
              />
              <ButtonIcon
                style={{ padding: 20 }}
                icon={'x-circle'}
                onClick={() => setState({ doquit: true })} 
              />
            </View>
          }
        </View>

        <View style={{ flex: 1, margin: 10, marginTop: 30 }}>
          {content[option]}
        </View>
      </View>
    </Screen>
  );
};
