import {
  UserAgent,
  Registerer,
  Inviter,
  Invitation,
  RegistererState,
  Session,
  SessionState,
  Web,
} from 'sip.js';

import { createRandomToken } from 'sip.js/lib/core/messages/utils';

Session.prototype.getStream = function () {
  try {
    const stream = new MediaStream();
    this.sessionDescriptionHandler?.peerConnection
      ?.getReceivers()
      .forEach(({ track }) => {
        if (track) stream.addTrack(track);
      });

    return stream;
  } catch (err) {
    console.error(err);
  }
};

Session.prototype.setMuted = function (muted) {
  this.sessionDescriptionHandler.localMediaStream?.getAudioTracks().forEach(track => {
    track.enabled = !muted;
  });

  this._muted = muted;
};

Session.prototype.setMutedVideo = function (muted) {
  this.sessionDescriptionHandler.localMediaStream?.getVideoTracks().forEach(track => {
    track.enabled = !muted;
  });

  this._mutedVideo = muted;
};

Session.prototype.setHold = async function (hold) {
  await this.invite({
    sessionDescriptionHandlerModifiers: hold ? [Web.holdModifier] : []
  });

  this._hold = hold;
};

Session.prototype.hold = async function () {
 this.setHold(true);
};

Session.prototype.unhold = async function () {
  this.setHold(false);
 };

Session.prototype.isHold = function () {
  return this._hold;
}

Session.prototype.isMuted = function () {
  return this._muted;
}

Session.prototype.isMutedVideo = function () {
  return this._mutedVideo;
}

Session.prototype.isVideo = function () {
  if (this.isInbound())
    return (
      this.request?.body?.includes?.('m=video') ||
      this.request?.body?.body?.includes?.('m=video')
    );

  return this.sessionDescriptionHandlerOptions.constraints?.video;
};

Session.prototype.isInbound = function () {
  return this instanceof Invitation;
};

Session.prototype.isEstablished = function () {
  return this.state === SessionState.Established;
};

Session.prototype.isDirtyAnswered = function () {
  return this.state === SessionState.Establishing && this.isInbound();
};

Session.prototype.autoanswer = function () {
  return this.request?.getHeader('X-Autoanswer');
};

Session.prototype.dtmf = function (key) {
  this.info({
    requestOptions: {
      body: {
        contentDisposition: 'render',
        contentType: 'application/dtmf-relay',
        content: `Signal=${key}\r\nDuration=1000`
      }
    }
  });
};

Session.prototype.hang = async function () {
  try {
    switch (this.state) {
      case SessionState.Initial:
      case SessionState.Establishing:
        this.isInbound() ? await this.reject() : await this.cancel();
        break;
      case SessionState.Established:
        await this.bye();
        break;
    }
  } catch (err) {
    console.error('sip hang', err);
  }
};

export class Cdr {
  constructor({ session }) {
    
    const secondsElapsed = () => {
      return Math.ceil((new Date() - this.date) / 1000);
    }

    const id =
      session.request.getHeader('X-Call-ID') ||
      session.request.getHeader('Call-ID');

    const {
      displayName,
      uri: { user, headers }
    } = session.remoteIdentity;

    const direction = session.isInbound() ? 'inbound' : 'outbound';

    this.id = id;
    this.direction = direction;
    this.from = session.isInbound()
      ? user
      : session.request.getHeader('P-Asserted-Identity');
    this.to = session.isInbound() ? displayName : user;
    this.headers = headers;

    this.video = session.isVideo();

    this.status = 'ringing';
    this.date = new Date();

    session.cdr = this;
    session.stateChange.addListener((state) => {
      switch (state) {
        case SessionState.Established:
          this.status = 'answered';
          this.wait = secondsElapsed();

          break;
        case SessionState.Terminated:
          this.status = this.status === 'answered' ? this.status : 'missed';

          this.wait = this.wait || secondsElapsed();
          this.total = secondsElapsed();
          this.duration = this.total - this.wait;
          break;
      }
    });
  }

  async setContact(contacts) {
    try {
      const { from, to, direction } = this;
      const phone = direction === 'inbound' ? from : to;
      this.contact = await contacts.contactByPhone({ phone });
    } catch (err) {
      console.error(err);
    }
  }

  isInbound() {
    return this.direction === 'inbound';
  }
}

export {
  UserAgent,
  Registerer,
  Inviter,
  Invitation,
  RegistererState,
  Session,
  SessionState,

  createRandomToken,
};
