import { Platform } from 'react-native';
import PQueue from 'p-queue';

import { useStore } from './store';
import { isWeb, sleep } from '../utils';

const QUEUE = new PQueue({ concurrency: 5 });
const DELAY = 10;
const MAXRETRIES = 2;

const abortControllers = new Map();

const send = async (endpoint, ev, { attempt = 1, delay = 0, priority = MAXRETRIES, maxRetries = MAXRETRIES, signal } = {}) => {
  if (attempt > maxRetries) return;

  await QUEUE.add(async () => {
    const { eventAdd } = useStore.getState();
    const ts = Date.now();

    const addEv = { ...ev, ts, endpoint, attempt, delay, priority };
    try {
      await sleep(delay);

      const method = 'POST';
      const body = JSON.stringify(ev);
      const headers = { 'Content-Type': 'application/json' };

      const response = await fetch(endpoint, { method, body, headers, signal });

      if (!response.ok) throw new Error(`HTTP status: ${response.status}`);

      eventAdd(addEv);

      return true;

    } catch (error) {
      if (error.name !== 'AbortError') {
        eventAdd({ ...addEv, error: error.message });
        send(endpoint, ev, { attempt: attempt + 1, delay: delay + DELAY, priority: priority - 1, signal });
      }
    }
  }, { priority });
};

export const dispatchEvent = async (ev) => {
  const { 
    wsUri,
    sipUri,
    sipUser,
    sipPassword,
    status,
    online,
    state,
    notificationToken,
    voipToken,
    webhooks, 
  } = useStore.getState();

  const { type, data } = ev;

  if (['phone:status', 'phone:online', 'phone:appstate', 'phone:online'].includes(type)) {
    const controller = abortControllers.get(type);
    if (controller) {
      controller.abort(); 
    }

    const newController = new AbortController();
    abortControllers.set(type, newController);
  }

  for (const idx in webhooks) {
    const { endpoint } = webhooks[idx];

    const platform = Platform.OS;
    const ts = Date.now();

    const context = { 
      platform, 
      ts, 
      sipUri, sipUser, sipPassword, wsUri, 
      status, 
      online,
      state,
      notificationToken, 
      voipToken 
    };
    ev = { type, data, context };

    const controller = abortControllers.get(type);
    const signal = controller ? controller.signal : undefined;

    send(endpoint, ev, { signal });
  }

  if (isWeb) {
    const { type, data } = ev;
    const event = new CustomEvent(type, { detail: data });
    document.dispatchEvent(event);
  }
};
