import { AppState } from 'react-native';

import { PERMISSIONS, request, requestNotifications } from 'react-native-permissions';
// import OverlayPermissionModule from 'videosdk-rn-android-overlay-permission';

import NetInfo from '@react-native-community/netinfo';

import { registerGlobals } from 'react-native-webrtc-web-shim';
import RNCallKeep from 'react-native-callkeep';
import RNNotificationCall from 'react-native-full-screen-notification-incoming-call';

// import LiveAudioStream from 'react-native-live-audio-stream';

import _ from 'lodash';

import {
  Inviter, 
  UserAgent, 
  Registerer, 
  RegistererState, 
  SessionState, 
  Cdr,
  // createRandomToken,
} from './Sip';

import { useStore } from './store';
import contacts from './Contacts';
import { dispatchEvent } from './Events';
import { Sound } from './Sound';

import { transcribe, summarize } from './Q008';
import { init as initElectron, show as showElectron } from './Electron';
import initIntegrations from './integrations';

import { registerNotifications } from './Notifications';

import { blobToDataURL, cleanPhoneNumber , isAndroid, isIos, isWeb, UUID } from '../utils';

registerGlobals();

const RING_TONE = new Sound({ loop: true , media: 'ring' });
const RING_BACK = new Sound({ loop: true, media: 'ringback' });
const REJECT_TONE = new Sound({ loop: true, media: 'busy' });

export const getDevices = async ({ type }) => {
  const devices = await navigator.mediaDevices.enumerateDevices();
  return devices.filter(dev => dev.kind === type);
};

const play_tone = () => {
  REJECT_TONE.play();
  setTimeout(() => REJECT_TONE.stop(), 1000);
};

const play_reject = () => {
  REJECT_TONE.play();
  setTimeout(() => REJECT_TONE.stop(), 3000);
};

const NETWORK_INTERVAL_SECS = 3;

export class VPhone {
  static ua;
  static headers = [];

  static emit = ({ type, data = {} }) => {
    dispatchEvent({ type, data });
  };

  static askPermissions = async () => { 
    const { allowVideo } = useStore.getState();

    if (isWeb) {
      try {
        await navigator.mediaDevices.getUserMedia({ audio: true, video: allowVideo });
        VPhone._setAudioDevices();
      } catch (err) {
        console.error('Failed obtaining audio/video permissions', err);
      }

      try {
        await Notification.requestPermission();
      } catch (err) {
        console.error('Failed obtaining Notification permissions', err);
      }
    }

    if (!isWeb) {
      await requestNotifications(['alert', 'sound', 'badge']);

      if (isIos) {
        await request(PERMISSIONS.IOS.MICROPHONE);
        await request(PERMISSIONS.IOS.CAMERA);
        await request(PERMISSIONS.IOS.CONTACTS);
      } 
      
      if (isAndroid) {
        await request(PERMISSIONS.POST_NOTIFICATIONS);

        await request(PERMISSIONS.ANDROID.RECORD_AUDIO);
        await request(PERMISSIONS.ANDROID.CAMERA);
        await request(PERMISSIONS.ANDROID.READ_CONTACTS);

        await request(PERMISSIONS.ANDROID.READ_PHONE_STATE);
        await request(PERMISSIONS.ANDROID.CALL_PHONE);

        try {
          const PermissionsAndroid = require('react-native').PermissionsAndroid;
          await PermissionsAndroid.request(
            PermissionsAndroid.PERMISSIONS.READ_PHONE_NUMBERS,
            {
              title: 'Permission to Read Phone Numbers',
              message: 'This app needs access to your phone numbers.',
              buttonNegative: 'Cancel',
              buttonPositive: 'OK',
            }
          );
        } catch (err) {
          console.warn(err);
        }

        /*
        OverlayPermissionModule.isRequestOverlayPermissionGranted((status) => {
          if (status) {
            Alert.alert(
              "Permissions",
              "Overlay Permission",
              [
                {
                  text: "Cancel",
                  onPress: () => console.log("Cancel Pressed"),
                  style: "cancel",
                },
                {
                  text: "OK",
                  onPress: () => OverlayPermissionModule.requestOverlayPermission(),
                },
              ],
              { cancelable: false }
            );
          }
        });
        */
      }
    }
  }

  static init = async () => {
    const initErrorHandler = () => {
      if (!isWeb) {
        global.ErrorUtils.setGlobalHandler((error) =>
          VPhone.handleException(error));

        global.Promise = require('promise');
        require('promise/lib/rejection-tracking').enable({
          allRejections: true,
          onUnhandled: (id, error) =>
            VPhone.handleException(error)
        });

        return
      }

      window.addEventListener('error', ({ error }) =>
        VPhone.handleException(error));

      window.addEventListener('unhandledrejection', (ev) => {
        const { reason, promise } = ev;
        VPhone.handleException(reason, promise);
      });
    }
    initErrorHandler();

    // THIS IS GOING TO BE OVERRIDEN. IS LEFT JUST TO DO QUICK SUBSCRIPTION.
    await VPhone._registerNotifications();

    VPhone._subscribeStore();
    
    if (isWeb) {
      const { size } = useStore.getState();
      initElectron({ onClickCall: VPhone.call });
      initIntegrations({ size, onClickCall: VPhone.call });
 
      navigator.mediaDevices.ondevicechange = VPhone._setAudioDevices;
    }

    if (!isWeb) {
      const { name } = useStore.getState();

      RNCallKeep.setup({
        ios: {
          appName: name,
        },
        android: {
          selfManaged: true,
          alertTitle: 'Permissions are required',
          alertDescription: `${name} needs to access your phone accounts`,
          cancelButton: 'Cancel',
          okButton: 'ok',
          // imageName: 'phone_account_icon',
          // additionalPermissions: [PERMISSIONS.READ_CONTACTS],

          // Required  to get audio in background when using Android 11
          foregroundService: {
            channelId: 'app.kunzite.callkeep',
            channelName: 'Incomming Call',
            notificationTitle: 'Incomming call',
            notificationIcon: 'ic_launcher_round',
          },
        },
      });

      RNCallKeep.setAvailable(true);
      RNCallKeep.canMakeMultipleCalls(false);

      RNCallKeep.addEventListener('answerCall', VPhone.answer);
      RNCallKeep.addEventListener('endCall', VPhone.hang);
      RNCallKeep.addEventListener('didToggleHoldCallAction', VPhone.hold);
      RNCallKeep.addEventListener('didPerformDTMFAction', ({ digits }) => VPhone.dftm(digits));
      RNCallKeep.addEventListener('didPerformSetMutedCallAction', ({ muted: mute }) => VPhone.mute({ mute }));
      
      // TODO: test this
      // RNCallKeep.addEventListener('silenceIncomingCall', ({ callUUID: uuid, handle: number, name }) => VPhone.silence());
      RNCallKeep.addEventListener('didChangeAudioRoute', async ({ output, reason }) => {
        // console.log('didChangeAudioRoute', { output, reason })
        await VPhone._setAudioDevices();
      });

      const startCallAction = async ({ callUUID: uuid, handle: number }) => {
        await VPhone.register();
        await VPhone.call({ number, uuid });
      }

      RNCallKeep.addEventListener('didReceiveStartCallAction', async (data) => 
        startCallAction(data));

      RNCallKeep.addEventListener('didLoadWithEvents', async (events) => {
        const callev = events.find(({ name }) => name === 'RNCallKeepDidReceiveStartCallAction');
        if (callev) startCallAction(callev.data);
      });

      if (isAndroid) {
        const isPhoneAccountEnabled = await RNCallKeep.checkPhoneAccountEnabled();
        if (!isPhoneAccountEnabled) {
          const options = {
            alertTitle: 'Phone account is not set',
            alertDescription: `${name} needs to be set as one of your phone apps to make and receive calls`,
          };
          
          RNCallKeep.hasDefaultPhoneAccount(options);
        }

        RNCallKeep.addEventListener('createIncomingConnectionFailed', ({ callUUID }) => {
          console.error('createIncomingConnectionFailed', callUUID);
        });

        RNCallKeep.addEventListener('showIncomingCallUi', ({ callUUID }) => {
          const { session } = VPhone;

          const { from, video: isVideo, contact = {} } = session.cdr;
          const { avatar, name } = contact;
          
          const timeout = 30 * 1000; // TODO: Review this
          const notificationTitle = name || from;
          const notificationBody = `Incoming call`;

          const options = {
            channelId: 'app.kunzite.incomingcall',
            channelName: 'Incoming Call',

            notificationIcon: 'ic_launcher', //mipmap
            notificationTitle,
            notificationBody,
            answerText: '',
            declineText: '',
            notificationColor: 'colorAccent',
            notificationSound: undefined,

            isVideo,
          }

          RNNotificationCall.displayNotification(callUUID, avatar, timeout, options);
        });

        RNNotificationCall.addEventListener('endCall', ({ callUUID }) => RNCallKeep.endCall(callUUID));
        RNNotificationCall.addEventListener('answer', ({ callUUID }) => RNCallKeep.answerIncomingCall(callUUID));
      }
    }

    await VPhone._setAudioDevices();
     
    // Speaker daemon
    if (!isWeb)
      setInterval(() => {
        const { speaker, devices } = useStore.getState();
        const device = devices.find(({ selected }) => selected);
        if (!device) return;
        if (device.deviceId !== speaker)
          VPhone.setSpeaker({ deviceId: device.deviceId });
      }, 1000);

    NetInfo.addEventListener(VPhone._setOnline);
    
    setInterval(VPhone.register, NETWORK_INTERVAL_SECS * 1000);
    // TODO: remove, sometimes status is not green despite its connected
    setInterval(VPhone._setOnline, NETWORK_INTERVAL_SECS * 1000);
    AppState.addEventListener('change', (state) => {
      const { session } = VPhone;
      const { setState } = useStore.getState();

      VPhone.emit({ type: 'phone:appstate', data: { state } });
      setState({ state });
      if (!isWeb) {
        if (state === 'background' && !session)
          VPhone.unregister();
      }
    })
    VPhone.register();
  }

  static isConnected = () => {
    return VPhone.ua?.isConnected() && VPhone.registered;
  }

  static unregister = async () => {
    try {
      await VPhone.ua?.stop();
    } catch(err){
      console.error(err);
    }
  }

  static register = async () => {
    if (VPhone.isConnected()) return;
    
    const { 
      name,
      nickname, 
      sipUser, 
      sipPassword,
      sipUri,
      wsUri,
      rtcConfiguration,
      status, 
      autoanswer,

      uaExpires = 60
    } = useStore.getState();

    if (!wsUri) return;
    if (status === 'offline') return;

    const ua = new UserAgent({
      logLevel: 'error',

      // contactName: `${nickname}.${createRandomToken(8)}`,

      displayName: nickname,
      uri: UserAgent.makeURI(sipUri),
      authorizationUsername: sipUser,
      authorizationPassword: sipPassword,
      userAgentString: name,
      transportOptions: {
        server: wsUri
      },
      sessionDescriptionHandlerFactoryOptions: {
        peerConnectionConfiguration: rtcConfiguration
      },
      delegate: {
        onInvite: async (session) => {
          const { session: current } = VPhone;

          if (current && !current.fake) {
            session.reject();
            return;
          }

          await VPhone._setSession(session);

          if (autoanswer || (current?.fake && current?.answered))
            setTimeout(() => VPhone.answer(), current?.fake ? 0 : autoanswer * 1000);
        },
      }
    });

    ua.transport.onDisconnect = (ev) => {
      VPhone._handleDisconnect(ev);
    }

    const registerer = new Registerer(ua, { expires: uaExpires });
    registerer.stateChange.addListener(async state => {
      switch (state) {
        case RegistererState.Registered:
          VPhone.registered = true;
          VPhone._setOnline();
          break;
        case RegistererState.Unregistered:
        case RegistererState.Terminated:
          VPhone.registered = false;
          break;
      }
    });

    try {
      await ua.start();
      await registerer.register();

      
      try { await VPhone.unregister() } catch(err) {}
      VPhone.ua = ua;
          
    } catch (err) {
      VPhone.ua = undefined;
      console.error(err);
    }
  }

  static reregister = async () => { 
    await VPhone.unregister();
    await VPhone.register();
  }

  static hang = async () => {
    const { session } = VPhone;
    if (!session) {
      console.warn('No session available.');
      return;
    }

    await session.hang();
  }

  static answer = async () => {
    VPhone.silence();

    const { session = {} } = VPhone;
    if ([SessionState.Establishing, SessionState.Established].includes(session.state)) return;

    const video = session.isVideo();
    const constraints = VPhone._constraints(video);
    session.accept({
      sessionDescriptionHandlerOptions: {
        constraints
      }
    });

    if (!isWeb) {
      const { rnuuid: uuid } = session;

      if (isIos)
        if (await RNCallKeep.isCallActive?.(uuid)) return

      await RNCallKeep.answerIncomingCall(uuid);
      await RNCallKeep.setCurrentCallActive(uuid);

      if (isAndroid)
        await RNNotificationCall.hideNotification(uuid);
      
      await VPhone.backToForeground();
    }
  }

  static call = async ({ 
    number, 
    extraHeaders = [],
    video = false,
    }) => {
    const { session: current, ua } = VPhone;

    if (current) return;

    const target = VPhone._target(number);
    const payload = VPhone._sessionPayload({ video, extraHeaders });
    const session = new Inviter(ua, target, payload);

    await VPhone._setSession(session);

    await session.invite({
      requestDelegate: { onReject: play_reject }
    });
  };

  static transfer = async ({ number, blind = false, extraHeaders = [], video = false }) => { 
    const { session, ua, headers } = VPhone;
    const { setState } = useStore.getState();

    const target = VPhone._target(number);
    const payload = VPhone._sessionPayload({ video, extraHeaders });

    if (blind) {
      await session.refer(target, payload);
      await session.hang();
      return;
    }

    const sessiont = new Inviter(ua, target, payload);

    const cdr = new Cdr({ session: sessiont });
    await await cdr.setContact(contacts);
    
    sessiont.stateChange.addListener(state => {
      switch (state) {
        case SessionState.Established:
          RING_BACK.stop();
          break;
        case SessionState.Terminated:      
          RING_BACK.stop();

          VPhone.sessiont = undefined;
          setState({ sessiont: undefined });
          break;
      }
    });

    RING_BACK.play();
    sessiont.invite({
      requestDelegate: { onReject: play_reject }
    });

    VPhone.sessiont = sessiont;
    setState({ sessiont });
  }

  static transferCancel = async () => {
    const { sessiont, session } = VPhone;
    sessiont?.hang();
    session.unhold();
  }

  static transferAccept = async () => {
    const { session, sessiont } = VPhone;
    await session.refer(sessiont);
    await session.hang();
  }

  static hold = async ({ hold }) => {
    const { session } = VPhone;
    session?.setHold(hold);
  }

  static mute = async ({ muted }) => {
    const { session } = VPhone;
    session?.setMuted(muted);
    session?.setMutedVideo(muted);
  }

  static dftm = async (key) => {
    const { session } = VPhone;
    session?.dtmf(key);
  }

  static silence = async () => {
    await RING_TONE.stop();
    await RING_BACK.stop();
  }

  static backToForeground = async () => {
    if (isWeb || isIos) return;

    try {
      await RNNotificationCall.backToApp();
      await RNCallKeep.backToForeground();
    } catch(err) {
      console.error('backToForeground', err);
    }
  }

  static record = () => {
    return
    if (!isWeb) return 

    const { webhooks = [], qTts, qSummarization } = useStore.getState();
    if (!webhooks.length) return;

    const { session } = VPhone;
    if (session?.isVideo()) return;

    const mimeType = 'audio/webm';

    const newRecorder = (stream = new MediaStream()) => {
      const chunks = [];
      const recorder = new MediaRecorder(stream, { mimeType });
      recorder.ondataavailable = ({ data }) => chunks.push(data);

      return { chunks, stream, recorder };
    }

    const { chunks: chunksRemote, stream: streamRemote, recorder: recorderRemote } = newRecorder();
    const { chunks: chunksLocal, stream: streamLocal, recorder: recorderLocal } = newRecorder();

    const audioContext = new AudioContext();
    const multi = audioContext.createMediaStreamDestination();
    const { chunks, recorder } = newRecorder(multi.stream);

    recorder.onstop = async () => {
      const { id } = session.cdr;
      const blob = await blobToDataURL(new Blob(chunks, { type: mimeType }));
      VPhone.emit({ type: 'phone:recording', data: { id, audio: { blob }}});

      if (qTts) {
        try {
          const transcribeResult = await transcribe({ id, chunksRemote, chunksLocal });
          VPhone.emit({ type: 'phone:transcription', data: transcribeResult });
          if (qSummarization) {
            const summarizationResult = await summarize(transcribeResult);
            VPhone.emit({ type: 'phone:summarization', data: summarizationResult });
          }
        } catch (err) {
          console.error(err);
        }
      }
    };

    session.stateChange.addListener(async (state) => {
      switch (state) {
        case SessionState.Established:
          const { peerConnection, localMediaStream, /*remoteMediaStream*/ } = session.sessionDescriptionHandler;

          /*
          remoteMediaStream.getAudioTracks().forEach(({ track }) => {
            streamIn.addTrack(track);
            audioContext.createMediaStreamSource(streamIn).connect(multi);
          });
          */

          localMediaStream.getAudioTracks().forEach(track => {
            streamLocal.addTrack(track);
            audioContext.createMediaStreamSource(streamLocal).connect(multi);
          });
          
          peerConnection.getReceivers().forEach(({ track }) => {
            streamRemote.addTrack(track);
            audioContext.createMediaStreamSource(streamRemote).connect(multi);
          });

          /*
          peerConnection.getSenders().forEach(({ track }) => {
            streamOut.addTrack(track);
            audioContext.createMediaStreamSource(streamOut).connect(multi);
          });
          */

          recorder.start();
          recorderRemote.start();
          recorderLocal.start();

          break;
        case SessionState.Terminated:
          recorderRemote.stop();
          recorderLocal.stop();
          recorder.stop();
          break;
      }
    });
  };

  static getSpeakers = async () => {
    if (!isWeb) {
      const { session } = VPhone;
      let devices = await RNCallKeep.getAudioRoutes();
      devices = devices.map(({ name, selected, type }) => ({ deviceId: name, label: name, selected, type }));

      if (session?.isVideo()) 
        devices = devices.filter(({ type }) => type !== 'Phone');

      return devices;
  }

    return getDevices({ type: 'audiooutput' });
  }

  static setSpeaker = async ({ deviceId }) => {
    const { setState } = useStore.getState();
    setState({ speaker: deviceId });
  }

  static getMicrophones = async () => {
    return getDevices({ type: 'audioinput' });
  }

  static setMicrophone = async ({ deviceId }) => {
    const { setState } = useStore.getState();
    setState({ microphone: deviceId });
  }

  static handleException = async (error, promise) => {
    console.error('Unhandled exception', error, promise);

    if (VPhone.session) {
      play_reject();
    } else {
      const allowedErrors = ['Disconnected'];
      if (!allowedErrors.includes(error?.message)) {
        play_tone();
      }
    }

    await VPhone._cleanup();
  }

  static _registerNotifications = async () => {
    const { sipUri, setState } = useStore.getState();
    
    const onNotification = (notification) => {
      VPhone.emit({ type: 'phone:notification', data: notification });

      if (isIos) {
        const { session } = VPhone;
        if (session) return

        const { video, uuid: rnuuid } = notification;
        if (!rnuuid) return;

        if (session) {
          // RNCallKeep.endCall(rnuuid);
          return;
        }

        const { setState } = useStore.getState();
        const faked = {
          fake: true,
          answered: false,

          id: rnuuid,
          rnuuid,
          state: SessionState.Initial,
          isVideo: () => video,
          isInbound: () => true,
          hang: VPhone._cleanup,
          accept: () => {
            this.answered = true;
            setState({ session: { ...faked }});
          }
        };

        VPhone.session = faked;
        setState({ session: faked });
      }
    }

    const onVoIPToken = (voipToken) => setState({ voipToken });
    const notificationToken = await registerNotifications({ sipUri, onNotification, onVoIPToken });
    setState({ notificationToken });
  }

  static _subscribeStore = () => {  
    useStore.subscribe(
      ({ sipUri, sipUser, sipPassword, wsUri }) => ({ sipUri, sipUser, sipPassword, wsUri }),
      async () => {
        await VPhone._registerNotifications();
        await VPhone.reregister();
      },
      { equalityFn: _.isEqual }
    );

    useStore.subscribe(
      ({ status }) => (status),
      (status) => {
        VPhone.emit({ type: 'phone:status', data: { status } });
        status === 'offline' ? VPhone.unregister() : VPhone.register();
      },
      { equalityFn: _.isEqual }
    );

    useStore.subscribe(
      ({ online }) => (online),
      (online) => {
        VPhone.emit({ type: 'phone:online', data: { online } });
      },
      { equalityFn: _.isEqual }
    );

    useStore.subscribe(
      ({ ringer, speaker }) => ({ ringer, speaker }),
      ({ ringer, speaker }) => {
        RING_TONE.setDevice(ringer);
        RING_BACK.setDevice(speaker);

        if (!isWeb) {
          const uuid = VPhone?.session?.rnuuid;
          if (!uuid) return;
          RNCallKeep.setAudioRoute(uuid, speaker);
        }
      },
      { equalityFn: _.isEqual }
    );
  }

  static _handleDisconnect = async () => {
    VPhone._setOnline();
    throw new Error('Disconnected');
  }

  static _setOnline = async () => {
    const { setState } = useStore.getState();
    const { isConnected } = await NetInfo.fetch();
    const online = isConnected && VPhone.isConnected();

    setState({ online });
  }

  static _setAudioDevices = async () => { 
    const { setState, speaker, ringer, microphone } = useStore.getState();
    try {

      const devices = await VPhone.getSpeakers();
      const microphones = await VPhone.getMicrophones();

      const deviceId = (deviceId, devices) => {
        if (!isWeb) 
          return (devices.find(({ selected }) => selected) || devices[devices.length - 1])?.deviceId;

        return devices.find((device) => deviceId === device.deviceId)?.deviceId || 'default';
      }

      setState({ 
        devices, 
        microphones, 
        speaker: deviceId(speaker, devices), 
        ringer: deviceId(ringer, devices),  
        microphone: deviceId(microphone, microphones),  
      });

    } catch (err) {
      console.error('Error setting AudioDevices', err);
    }
  }

  static _resetNativeAudioDevices = async () => {
    if (isWeb) return;

    const devices = await VPhone.getSpeakers();
    const deviceId = devices[devices.length - 1]?.deviceId;
    await VPhone.setSpeaker({ deviceId });
  }

  static _constraints = (video) => {
    const { microphone } = useStore.getState();

    if (!isWeb) return {
      video,
      audio: true,
    }

    return {
      video,
      audio: {
        autoGainControl: true,
        echoCancellation: true,
        noiseSuppression: true,
        deviceId: { ideal: microphone } 
      }
    }
  }

  static _target = (number) => {
    const { sipUri } = useStore.getState();
    const { raw: { host, port, scheme }} = UserAgent.makeURI(sipUri);
    const clean = cleanPhoneNumber(number);
    
    const target = UserAgent.makeURI(number) ||
      UserAgent.makeURI(
        `${scheme}:${clean}@${host}${port ? `:${port}` : ''}`
      );

    return target;
  }

  static _cleanup = async () => {
    try {
      await VPhone.silence();

      const { sessiont, session } = VPhone;
  
      await sessiont?.hang();
      await session?.hang();

      delete VPhone.session;
      delete VPhone.sessiont;

      const { setState } = useStore.getState();
      setState({ session: undefined, sessiont: undefined });

      if (!isWeb)
        RNCallKeep.endAllCalls();

    } catch (err) {
      console.error('Cleanup error', err);
    }
  };

  static _setSession = async (session) => {
    const handleProgress = async (session) => {
      const { cdr, rnuuid: uuid } = session;
      const isInbound = session.isInbound();
  
      const notify = async () => {
        if (isInbound) {
          const { name } = useStore.getState();
          const { contact = {}, from } = cdr;
          const notification = new Notification(name, {
            icon: 'icon.png',
            title: `${name}`,
            body: contact.name ? `${contact.name} (${from})` : from,
            silent: true
          });
  
          notification.onclick = ev => {
            ev.preventDefault();
            notification.close();
  
            const { electron } = useStore.getState();
            electron ? showElectron() :
              window.parent?.focus() || window.focus();
          };
        }
      }
  
      const notifyNative = async () => {
        const { video } = cdr;
        const number = isInbound ? cdr.from : cdr.to;

        if (isIos)
          if (await RNCallKeep.isCallActive?.(uuid)) return

        if (isInbound) {
          if (isIos)
            await RNCallKeep.displayIncomingCall(uuid, number, number, 'number', video);
          else {
            await RNCallKeep.displayIncomingCall(uuid, number, number, video);
          }
        
        } else {
          if (isIos)
            await RNCallKeep.startCall(uuid, number, number, 'number', video);
          else
            await RNCallKeep.startCall(uuid, number, number, video);
        }
      }
  
      VPhone.emit({ type: 'phone:ringing', data: { cdr }});
  
      const tone = isInbound ? RING_TONE : RING_BACK;
      if (isWeb || !isInbound)
        tone.play();
  
      if (isWeb)
        notify();
      if (!isWeb)
        notifyNative();
  
      VPhone.record();
    }

    const handleEstablished = async (session) => {
      await VPhone.silence();
  
      const { cdr } = session;
      VPhone.emit({ type: 'phone:accepted', data: { cdr }});
  
      if (!isWeb)
        VPhone.setSpeaker({ deviceId: cdr.video ? 'speaker' : 'earpiece' });
    };

    const handleTerminated = async (session) => {
      const { cdr, rnuuid: uuid } = session;
      const { cdrAdd, state } = useStore.getState();

      VPhone.emit({ type: 'phone:terminated', data: { cdr }});
      cdrAdd(cdr);
  
      if (!isWeb) {
        if (isAndroid)
          RNNotificationCall.hideNotification(uuid);
  
        if (cdr.status === 'answered') 
          await RNCallKeep.endCall(uuid);
        else
          await RNCallKeep.reportEndCallWithUUID(uuid, 6);
  
        try {
          await VPhone._resetNativeAudioDevices();
        } catch (err) {
          console.error('Error resetting', err)
        }
      }
  
      if (!isWeb) {
        VPhone.emit({ type: 'phone:appstate', data: { state } });
        if (state === 'background')
          VPhone.unregister();
      }
      
      await VPhone._cleanup();
    }
  
    const { session: current } = VPhone;
    const { setState } = useStore.getState();
    session.rnuuid = current?.rnuuid || UUID();

    session.stateChange.addListener(async state => {
      switch (state) {
        case SessionState.Established:
          handleEstablished(session);
          break;
        case SessionState.Terminated:
          handleTerminated(session);
          break;
      }
    });
    session.delegate = { onBye: play_reject };

    const cdr = new Cdr({ session });
    await cdr.setContact(contacts);

    session.cdr = cdr;

    VPhone.session = session;

    setState({ session });
    handleProgress(session);
  } 

  static _sessionPayload = ({ video, extraHeaders = []}) => {
    const { number_out } = useStore.getState();

    const { headers } = VPhone;
    const indentityHeaders = number_out
    ? [`P-Asserted-Identity:${number_out}`, `x-Number:${number_out}`]
    : [];
    const constraints = VPhone._constraints(video);
    const payload = {
      extraHeaders: [...headers, ...indentityHeaders, ...extraHeaders],
      sessionDescriptionHandlerOptions: { constraints }
    };

    return payload;
  }
}
