import ZAFClient from 'zendesk_app_framework_sdk';

import contacts from '../Contacts';

export const init = async ({ size, onClickCall }) => {
  const ZAF = ZAFClient.init();

  if (!ZAF) return;

  contacts.query = async ({ query }) => {
    const zdQuery = query ? `query=${query}` : '';
    const url = `/api/v2/users/search.json?${zdQuery}`;
    let { count, users } = await ZAF.request({ url, type: 'GET', dataType: 'json' });
    users = users.map(({ id, name, phone }) => ({ id, zendeskId: id, name, phones: [phone] }));

    return { hits: users, total: count };
  }

  ZAF.invoke('resize', { width: `${size.width}px`, height: `${size.height}px` });

  document.addEventListener('phone:online', ({ detail: { online } }) => {
    ZAF.set('iconSymbol', online ? 'default' : 'red');
  });

  document.addEventListener('phone:ringing', () => {
    ZAF.invoke('popover');
  });

  document.addEventListener('phone:contactclick', async ({ detail: { contact = {} } }) => {
    if (!contact.zendeskId) return;

    try {
      const { currentUser } = await ZAF.get('currentUser');
      const url = `/api/v2/channels/voice/agents/${currentUser.id}/users/${contact.zendeskId}/display.json`;
      await ZAF.request({ url, type: 'POST', dataType: 'json' });
    } catch (err) {
      console.error('Zendesk integration', err);
    }
  });

  ZAF.on('voice.dialout', ({ number, ...rest } = {}) => {
    console.log(number)
    ZAF.invoke('popover');

    onClickCall?.({ 
      number, 
      extraHeaders: ['source: zendesk', `zendesk-ticket-id: ${rest.ticketId}`],
    })
  });
}
