
import { useEffect, useState } from 'react';
import { View, Pressable, FlatList } from 'react-native';

import {
  Menu,
  MenuOptions,
  MenuOption,
  MenuTrigger,
  renderers
} from 'react-native-popup-menu';

import moment from 'moment';

import { BORDERCOLOR, COLORS, CallIcon, AvatarContact, Icon, Text, TextInput, ButtonIcon, fontSizes } from './Basics';

import contacts from '../phone/Contacts'
import { isWeb, readFileAsText, UUID } from '../utils';

const { Popover } = renderers;

const PADDING = 10;
const CELL_HEIGHT = 45;

const Cell = ({ children, style, onPress }) => { 
  const defStyle = { flex: 1, minHeight: CELL_HEIGHT, marginVertical: PADDING / 2, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', paddingHorizontal: 15 };
  return (
    <Pressable 
      style={[defStyle, style]}
      onPress={onPress}
    >
      {children}
    </Pressable>
  );
}

const SearchInput = ({ onChange, value, style }) => (
  <View style={[
    { flexDirection:'row', borderBottomWidth: 1, borderBottomColor: BORDERCOLOR, paddingBottom: PADDING, marginBottom: PADDING, paddingHorizontal: 15 }, 
    style 
  ]}>
    <Icon icon='search' color={COLORS.textSecondary} />

    <TextInput
      style={{ flex: 1, marginLeft: 10 }}
      onChangeText={text => onChange?.(text)}
      value={value}
    />
  </View>
);

const List = ({
  data = [],
  renderItem,
  onFilterChange,
  showFilter,

  total,
  maxItems = 500,
  style
}) => {

  const [filter, setFilter] = useState('');

  const onFilterChangeHandler = (text) => {
    setFilter(text);
    onFilterChange?.(text);
  };

  return (
    <View style={[{ flex: 1 }, style ]}>
      {showFilter && (
        <SearchInput
          value={filter}
          onChange={onFilterChangeHandler}
        />
      )}

      {data?.length > 0 ? (
        <FlatList
          style={{ flex: 1 }}
          data={data.slice(0, maxItems)}
          // extraData={data}
          renderItem={renderItem}
          keyExtractor={(item) => item.id || item.name || UUID()}
        />
      ) : (
        <View style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}>
          <Icon size={30} color={COLORS.textSecondary} icon='eye' />
        </View>
      )}

      {data?.length > maxItems && (
        <View
          style={{ flexDirection: 'row', alignItems: 'center', paddingHorizontal: 15 }}
        >
          <Text
            style={{
              flex: 1,
              fontSize: fontSizes.s,
              textAlign: 'right',
            }}
          >
            {maxItems} / {total || data.length}
          </Text>
        </View>
      )}
    </View>
  )
};

const CdrCell = ({ cdr = {}, onClick, lang = 'en' }) => {
  const { direction, from, to, date, contact = {}, video } = cdr;
  const destination = direction === 'inbound' ? from : to;
  const { name } = contact;
  const displayName = name? `${name || ''} (${destination})` : destination;

  const callDate = moment(date).locale(lang).calendar({
    sameDay: 'LT',
    lastDay: `[${moment(date).calendar().split(' ')[0]}]`,
    lastWeek: 'dddd'
  });

  const subcellStyle = { justifyContent: 'center', marginRight: PADDING }
  return (
    <Cell onPress={() => onClick?.(destination, video)}>
      <View style={subcellStyle}>
        <AvatarContact contact={cdr.contact} />
      </View>

      <View style={{ ...subcellStyle, flex: 1, justifyContent: 'space-evenly' }}>
        <Text numberOfLines={1} style={{ fontSize: fontSizes.s }}>
          {displayName}
        </Text>

        <Text style={{ fontSize: fontSizes.s, color: COLORS.textSecondary }} >
          {callDate}
        </Text>
      </View>

      {video &&
        <View style={subcellStyle}>
          <Icon icon="video" size={15} color={COLORS.textSecondary} />
        </View>
      }
      <View style={subcellStyle}>
        <CallIcon call={cdr} size={15} />
      </View>
    </Cell>
  );
}

const ContactCell = ({ contact = {}, onClick, onClickNumber, allowVideo }) => (
  <Cell onPress={() => onClick?.(contact)}>
    <AvatarContact contact={contact} />

    <View style={{ flex: 1, justifyContent: 'center', paddingLeft: PADDING }}>
      <Text numberOfLines={1} style={{ fontSize: fontSizes.s }} >{contact.name || contact.phones?.[0]}</Text>
    </View>

    <Menu renderer={Popover} >
      <MenuTrigger>
        <ButtonIcon icon="phone" size={15} />
      </MenuTrigger>

      <MenuOptions>
        {contact.phones.map((phone, i) => {
          return (
            <MenuOption
              key={`contact-phone-${i}`} >
                <Cell>
                  <Text size={22} style={{ paddingRight: 10 }}>{phone}</Text>
                  <ButtonIcon color={COLORS.success} style={{ padding: 10 }} icon="phone" onClick={() => onClickNumber?.(phone)} />
                  {allowVideo &&
                    <ButtonIcon color={COLORS.primary} style={{ padding: 10 }} icon="video" onClick={() => onClickNumber?.(phone, true)} />
                  }
                </Cell>
            </MenuOption>
          );
        })}
      </MenuOptions>
    </Menu>
  </Cell>
)

const WebhookCell = ({ webhook, onClick }) => {
  const { label, endpoint } = webhook;

  return (
    <Cell onPress={() => onClick?.(webhook)}>
      <View style={{ flex: 1, }}>
        <Text numberOfLines={1} style={{ fontSize: fontSizes.s }} >{label || endpoint}</Text>
        <Text style={{ fontSize: fontSizes.s, color: COLORS.textSecondary }}>{endpoint}</Text>
      </View>
    </Cell>
  );
}

const EventCell = ({ event, lang = 'en' }) => {
  const { endpoint, type, ts, error, data } = event;
  const color =  error ? COLORS.danger : COLORS.textSecondary;
  const date = moment(ts).locale(lang).calendar({
    sameDay: 'LT',
    lastDay: `[${moment(ts).calendar().split(' ')[0]}]`,
    lastWeek: 'dddd'
  });
  return (
    <Cell>
      <View style={{ flex: 1, }}>
        <Text numberOfLines={1} style={{ color, fontSize: fontSizes.s }} >{type}</Text>
        <Text style={{ fontSize: fontSizes.s, color: COLORS.textSecondary }}>{endpoint}</Text>
        <Text style={{ fontSize: fontSizes.s, color: COLORS.textSecondary }}>{JSON.stringify(data)}</Text>
        <Text style={{ fontSize: fontSizes.s, color: COLORS.textSecondary }}>{date}</Text>
      </View>
    </Cell>
  );
}

export const CdrsList = (props) => (
  <List {...props} renderItem={({ item }) =>
    <CdrCell cdr={item} onClick={props?.onClick} />} />
)

export const ContactsList = ({ style, maxItems, onClick, onClickNumber, allowVideo }) => {
  const [ data, setData ] = useState();
  const [ total, setTotal ] = useState(0);

  const onFilterChange = async (text) => {
    const debounceTimeout = setTimeout(async () => {
      setData(await contacts.query({ query: text, max: maxItems }));
    }, 300);

    return () => clearTimeout(debounceTimeout);
  }

  useEffect(() => { 
    const setAllContacts = async () => {
      const result = await contacts.query({ max: maxItems });
      setData(result);
      setTotal(result.total);
    }

    setAllContacts();

    if (isWeb) {
      document.addEventListener('indexing:end', setAllContacts);

      return () => {
        document.removeEventListener('indexing:end', setAllContacts);
      }
    }
  }, []);

  if (isWeb && !total) 
    return <ContactsDrop />;

  return (
    <List 
      data={data?.hits} 
      total={data?.total} 
      showFilter={true}
      onFilterChange={onFilterChange}
      style={style} 
      maxItems={maxItems} 
      renderItem={({ item }) => 
        <ContactCell contact={item} onClick={onClick} onClickNumber={onClickNumber} allowVideo={allowVideo} />} />
  )
}

export const WebhooksList = (props) => (
  <List {...props} renderItem={({ item }) =>
    <WebhookCell webhook={item} onClick={props?.onClick} />} />
)

export const EventsList = (props) => (
  <List {...props} renderItem={({ item }) =>
    <EventCell event={item} />} />
)

export const ContactsDrop = () => {
  const onDragOver = ev => {
    ev.preventDefault();
    ev.stopPropagation();
  };

  const onDrop = async ev => {
    ev.preventDefault();
    ev.stopPropagation();
    const { files } = ev.dataTransfer;
    const [file] = files;
    const vcf = await readFileAsText(file);

    contacts.index({ vcf });
  };

  const style = {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%',
  }

  return (
    <View style={{ flex: 1 }}>
      <div
        draggable
        onDragOver={onDragOver}
        onDrop={onDrop}
        style={style}
      >
        <Text style={{ textAlign: 'center', fontSize: fontSizes.m }}>
          Drop a VCF file to add contacts
        </Text>
      </div>
    </View>
  );
};
