import { Pressable, View } from 'react-native';

import { COLORS, AvatarUser, Select, Text, fontSizes, resizeRel } from './Basics';

export const Header = ({
  numbers = [],
  number_out,
  onChange,

  name,
  avatar,
  status_color,
  onSettingsClick,

  style
}) => {
  const hasNumbers = numbers.length > 0;
  const avatarSize = 46;
  const numbersWidth = 180;

  const options = numbers.map(({ number }) => {
    return {
      label: number,
      value: number
    };  
  });

  const { value } = options.find(({ value }) => value === number_out) || options[0] || {};

  const itemFontStyle =  { fontSize: fontSizes.l };
  const backgroundColor = COLORS.backColor;

  return (
    <View style={[{ justifyContent: 'center',  alignItems: 'center' }, style]}>
      <View style={{ width: '100%', flexDirection: 'row', alignItems: 'center' }}>
        <View style={{ width: '15%' }}/>

        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', borderRadius: resizeRel(avatarSize) / 2, backgroundColor }} >
          <Pressable onPress={onSettingsClick} >
            <AvatarUser avatar={avatar} color={status_color} size={avatarSize} />
          </Pressable>

          {!hasNumbers &&
            <Text numberOfLines={1} style={{ fontSize: fontSizes.l, flex: 1, textAlign: 'center', paddingHorizontal: 5 }}>{name}</Text>
          }

          {hasNumbers &&
            <View style={{ justifyContent: 'center',  alignItems: 'center' }}>
              <Select
                key={value}
                tabIndex="-1"
                options={options}
                value={value}
                onChange={onChange}
                buttonStyle={{ borderWidth: 0, backgroundColor: '#0000', width: numbersWidth }}
                renderCustomizedButtonChild={(item) => (
                  <View style={{ flex: 1 }}>
                    <Text numberOfLines={1} style={{ fontSize: fontSizes.l, flex: 1, textAlign: 'center', paddingHorizontal: 5 }}>{name}</Text>
                    <Text numberOfLines={1} style={{ ...itemFontStyle, color: COLORS.textSecondary, flex: 1, textAlign: 'center' }}>{item?.value}</Text>
                  </View>
                )}
                rowTextStyle={{ ...itemFontStyle, height: 25, textAlign: 'center' }}
                dropdownStyle={{ backgroundColor: '#ff00ff' }}
                // renderDropdownIcon={() => {}}
              />
            </View>
          }
          </View>

          <View style={{ width: '15%' }}/>
      </View>
    </View>
  )
}
