import { useEffect, useState } from 'react';
import { Linking, View } from 'react-native';
import { MenuProvider } from 'react-native-popup-menu';

import { VPhone } from '../phone/VPhone';
import { useStore } from '../phone/store';
import { linking } from '../phone/Electron';

import { Screen } from './Basics';
import { Dialer } from './Dialer';
import { Header } from './Header';
import { Container } from './Container';

import { SessionScreen } from './SessionScreen';
import { SettingsScreen } from './SettingsScreen';

import { isWeb } from '../utils';
import { SessionState } from 'sip.js';

const Phone = () => {
  const [ showSettings, setShowSettings ] = useState(false);

  const [ showTransfer, setShowTransfer ] = useState(false);
  const [ transferBlind, setTransferBlind ] = useState(false);

  const { 
    session,
    sessiont,
    
    avatar,
    nickname,
    sipUri = '',
    sipUser = '',

    numbers,
    number_out,

    statuses,
    status,
    online,

    speaker,

    cdrs = [],

    allowTransfer,
    allowBlindTransfer,
    allowVideo = true,

    setState
  } = useStore();
  
  useEffect(() => {
    VPhone.askPermissions();
  }, []);

  const onNumberChangeHandler = (number_out) => setState({ number_out });

  const contactClickHandler = async (contact) => {
    const type = 'phone:contactclick';
    VPhone.emit(type, { contact });

    const { url } = contact;
    if (url)
      isWeb ? linking({ url }) : await Linking.openURL(url);
  };

  const transferHandler = async (number) => {
    await VPhone.transfer({ number, blind: transferBlind });
    setShowTransfer(false);
  }

  const transferOnCancelHandler = async () => {
    VPhone.transferCancel();
    setShowTransfer(false);
  };
  
  const showTransferDialerHandler = async (blind = false) => {
    await session.setHold(true);
    setShowTransfer(true);
    setTransferBlind(blind);
  };

  const callHandler = async (number, video) => {
    await VPhone.call({ number, video });
  };

  const [sipUriName] = sipUri.replace('sip:', '').split('@');
  const displayName = nickname || sipUser || sipUriName || '';

  const status_color = statuses.find(
    item => item.value === (online ? status : 'offline'))?.color;

  const sessionfake = {
    // fake: true,
    answered: false,

    id: '99wee--wwe-wewe',
    rnuuid: '99wee--wwe-wewe',
    state: SessionState.Established,
    isVideo: () => true,
    isInbound: () => true,
    isEstablished: () => true,
    hang: VPhone._cleanup,
    accept: () => {},
   cdr: {
      direction: 'inbound',
      from: '+1 111 222 333',
      to: 'bob',
      contact: {
        phones: ['123456789'],
        name: 'Alice',
        avatar: 'https://t4.ftcdn.net/jpg/02/79/66/93/360_F_279669366_Lk12QalYQKMczLEa4ySjhaLtx1M2u7e6.jpg',
        avideo: 'https://media.istockphoto.com/id/1319103417/photo/inspired-female-teacher-in-headphones-meet-students-online-give-class.jpg?s=612x612&w=0&k=20&c=cSGIQIwPFpVi7m4MR2_SLlwDcpBELdnNnLNgdtH6Bak='
      }
    }
  };

  return (
    <MenuProvider style={{ flex: 1 }}>
      <Container>
        <View style={{ flex: 1 }}>
          <Header
            style={{ marginTop: 10 }}
            name={displayName}
            avatar={avatar}
            numbers={numbers}
            number_out={number_out}
            status_color={status_color}
            onChange={onNumberChangeHandler}
            onSettingsClick={() => setShowSettings(true)}
          />

          <Dialer
            style={{ marginTop: 25 }}
            key={session?.id}

            onDialClick={callHandler}
            onDialClickVideo={number => callHandler(number, true)}
            
            cdrs={cdrs}
            onCdrClick={callHandler}

            onContactClick={(phones = []) => callHandler(phones[0])}
            onContactClickNumber={callHandler}
            allowVideo={allowVideo}
          />
        </View>

        <SettingsScreen 
          visible={showSettings} 
          closeable={true} 
          onClose={() => setShowSettings(false)}
        />

        <SessionScreen
          session={session}
          speaker={speaker}

          onCancel={VPhone.hang}
          onAccept={VPhone.answer}

          allowTransfer={allowTransfer}
          allowBlindTransfer={allowBlindTransfer}
          onTransfer={() => showTransferDialerHandler(false)}
          onBlindTransfer={() => showTransferDialerHandler(true)}
        
          onContactClick={contactClickHandler}
        />

        <Screen 
          visible={session && showTransfer}
          closeable
          onClose={transferOnCancelHandler}
        >
          <View style={{ flex: 1, marginTop: 30 }}>
            <Dialer
              testID="transferDialer"
              isTransfer={true}

              onDialClick={transferHandler}

              cdrs={cdrs}
              onCdrClick={transferHandler}

              onContactClick={(phones = []) => transferHandler(phones[0])}
              onContactClickNumber={transferHandler}
            />
          </View>
        </Screen>

        <SessionScreen
          session={sessiont}
          speaker={speaker}

          onCancel={transferOnCancelHandler}
          onAccept={VPhone.transferAccept}

          isTransfer={true}
        />

      </Container>
    </MenuProvider>
  )
};

export default Phone;
