import { useState, useEffect } from 'react';
import { Pressable, View } from 'react-native';

import { Sound } from '../phone/Sound';
import { ButtonIcon, COLORS, fontSizes, RoundIconButton, Text, TextInput, resizeRel } from './Basics';
import { CdrsList, ContactsList } from './Lists';

const keys = [
  { keypad: '1', sub: '' },
  { keypad: '2', sub: 'ABC' },
  { keypad: '3', sub: 'DEF' },
  { keypad: '4', sub: 'GHI' },
  { keypad: '5', sub: 'JKL' },
  { keypad: '6', sub: 'MNO' },
  { keypad: '7', sub: 'PQRS' },
  { keypad: '8', sub: 'TUV' },
  { keypad: '9', sub: 'WXYZ' },
  { keypad: '*', sub: '' },
  { keypad: '0', sub: '+' },
  { keypad: '#', sub: '' }
];

const tones = {};
keys.forEach(async ({ keypad }) => {
  const key = keypad.replace('#', 'hash').replace('*', 'star');
  tones[keypad] = new Sound({ media: `dtmf${key}` });
});

const DialButton = ({ style, item, onPress, onLongPress, fontSize = fontSizes.xl, secondFontSize = fontSizes.xs }) => {
  const { keypad, sub } = item;

  return (
    <Pressable
      key={keypad}
      focusable={false}
      tabIndex="-1"
      style={[{
        flex: 1,
        justifyContent: 'flex-start',
        alignItems: 'center',
      }, style ]}
      onPress={() => {
        tones[keypad].play?.();
        onPress?.(keypad);
      }}
      onLongPress={() => {
        if (sub.length === 1) onLongPress?.(sub);
      }}
    >
      <Text style={{ fontSize }}>{keypad}</Text>
      <Text style={{ fontSize: secondFontSize }}>{sub}</Text>
    </Pressable>
  );
};

export const DialGrid = ({ style, buttonStyle, ...events }) => {
  const Row = ({ keys }) => (
    <View style={{ flex: 1, flexDirection: 'row' }}>
      {keys.map((item, idx) => (
        <DialButton 
          fontSize={fontSizes.xl}
          secondFontSize={fontSizes.xs}
          key={`dialbtn-${idx}`} 
          item={item} 
          {...events} 
          style={[buttonStyle]} />
      ))}
    </View>
  );

  return (
    <View
      style={[{
        flex: 1,
        justifyContent: 'space-evenly'
      }, style]}
    >
      <Row keys={keys.slice(0,3)} />
      <Row keys={keys.slice(3,6)} />
      <Row keys={keys.slice(6,9)} />
      <Row keys={keys.slice(9)} />
    </View>
  )
};

export const DialPad = ({ number = '', onClick, onClickVideo, isTransfer, style, testID }) => {
  const [value, setValue] = useState(number);

  useEffect(() => {
    setValue(number);
  }, [number]);

  const onPressDialer = data => setValue(value + data);
  const onPressDelete = () => setValue(value.substring(0, value.length - 1));
  
  const iconSize = 20;
  const buttonCallSize = 60;
  const cameraCallSize = 50;
  const appColor = COLORS.app;

  return (
    <View style={[{ flex: 1 }, style]}>
      <View 
        style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', paddingVertical: 10, borderColor: COLORS.borderColor, borderBottomWidth: 1, }}
      >
        <TextInput
          style={{ flex: 1, fontSize: fontSizes.xl, textAlign: 'center' }}
          value={value}
          onChangeText={text => setValue(text)}
          testID={`${testID? testID : ''}dialerTextInput`}
          showSoftInputOnFocus={false}
          onKeyPress={e => e.keyCode === 13 && onClick?.(value)}
        />
        <ButtonIcon size={20} icon="delete" onClick={onPressDelete} color={COLORS.textPrimary } />
      </View>

      <DialGrid style={{ marginTop: 10 }} onPress={onPressDialer} onLongPress={onPressDialer} />

      <View style={{ marginTop: 10 }}>
        <View style={{ flexDirection: 'row', justifyContent: 'center' }}>
          {!isTransfer &&
            <View>
              <RoundIconButton
                testID="callButton"
                size={buttonCallSize}
                color={COLORS.secondary}
                iconColor="white"
                icon="phone"
                iconSize={iconSize}
                onClick={() => onClick?.(value)} 
              />

              {onClickVideo &&
               <View style={{ alignItems: 'center', justifyContent: 'center', width: resizeRel(cameraCallSize + 5), height: resizeRel(cameraCallSize + 5), borderRadius: resizeRel(cameraCallSize + 5) / 2, position: 'absolute', left: resizeRel(cameraCallSize + 5) - 5 , backgroundColor: appColor }}>
                  <RoundIconButton
                    testID="videoCallButton"
                    size={cameraCallSize}
                    color={COLORS.primary}
                    iconColor="white"
                    icon="video"
                    iconSize={iconSize}
                    onClick={() => onClickVideo?.(value)} 
                  />
                </View>
              }
            </View>
          }

          {isTransfer &&
            <ButtonIcon
              testID="transferButton"
              icon="phone-forwarded"
              size={iconSize}
              style={{ backgroundColor: COLORS.secondary, width: 50, height: 50, borderRadius: 30 }}
              color="white" 
              onClick={() => onClick?.(value)} 
            />
          }
        </View>
      </View>
    </View>
  );
};

const tabs = [
  { id: 'dialer', icon: 'grid' },
  { id: 'cdrs', icon: 'clock' },
  { id: 'contacts', icon: 'users' }
];

export const Dialer = ({
  number = '',
  onDialClick,
  onDialClickVideo,

  cdrs = [],
  onCdrClick,

  onContactClick,
  onContactClickNumber,
  allowVideo,

  style,
  isTransfer,
  testID
}) => {
  const [tab, setTab] = useState('dialer');

  return (
    <View style={[{ flex: 1 }, style]}>
      {tab === 'dialer' && (
        <DialPad
          testID={testID}
          style={{ marginHorizontal: 40 }}
          onClick={onDialClick} 
          onClickVideo={allowVideo ? onDialClickVideo : undefined} 
          number={number}
          isTransfer={isTransfer}
        />
      )}

      {tab === 'cdrs' && (
        <CdrsList 
          data={cdrs} 
          onClick={(number, video) => onCdrClick?.(number, video)} 
        />
      )}

      {tab === 'contacts' && (
        <ContactsList
          onClick={({ phones = [] }) => onContactClick?.(phones)}
          onClickNumber={onContactClickNumber}
          allowVideo={allowVideo}
        />
      )}

      <View
        style={{
          flexDirection: 'row',
          justifyContent: 'space-around',
          alignItems: 'center',
          borderTopWidth: 1,
          borderColor: COLORS.borderColor,
          marginTop: 10
        }}
      >
        {tabs.map(({ id, icon }) => (
          <ButtonIcon
            style={{ height: 50, width: 50 }} 
            key={id} 
            color={tab === id ? COLORS.primary : COLORS.textPrimary}
            icon={icon} 
            onClick={() => setTab(id)} 
          />
        ))}
      </View>
    </View>
  );
};
